BEGIN;CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;SELECT extensions.no_plan();
SET LOCAL ROLE authenticated;SELECT lab_test.claim('11111111-1111-4111-8111-111111111111','authenticated');SELECT extensions.ok(lab_test.student((SELECT id FROM public.entities WHERE short_code='IETA'),(SELECT id FROM public.branches WHERE branch_code='KL'AND entity_id=(SELECT id FROM public.entities WHERE short_code='IETA'))),'[REG] Owner student create/edit, number, masking');SELECT extensions.ok(lab_test.academic((SELECT id FROM public.entities WHERE short_code='IETA'),(SELECT id FROM public.branches WHERE branch_code='KL'AND entity_id=(SELECT id FROM public.entities WHERE short_code='IETA')),'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1'),'[REG] Owner programme/intake/enrolment create/edit and number');RESET ROLE;
SET LOCAL ROLE authenticated;SELECT lab_test.claim('22222222-2222-4222-8222-222222222222','authenticated');SELECT extensions.ok(lab_test.student((SELECT id FROM public.entities WHERE short_code='IETA'),(SELECT id FROM public.branches WHERE branch_code='KL'AND entity_id=(SELECT id FROM public.entities WHERE short_code='IETA'))),'[REG] KL student create/edit, number, masking');SELECT extensions.ok(lab_test.academic((SELECT id FROM public.entities WHERE short_code='IETA'),(SELECT id FROM public.branches WHERE branch_code='KL'AND entity_id=(SELECT id FROM public.entities WHERE short_code='IETA')),'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1'),'[REG] KL programme/intake/enrolment');SELECT extensions.ok((SELECT count(*)>0 FROM public.find_student_duplicate_warnings('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1',(SELECT id FROM public.entities WHERE short_code='IETA'),'Fictional KL One','other','KL-IDENTITY-1111','+60121110001','kl@example.invalid',DATE'2000-01-01')),'[REG] KL duplicate detection');SELECT extensions.ok(lab_test.import_flow((SELECT id FROM public.entities WHERE short_code='IETA'),(SELECT id FROM public.branches WHERE branch_code='KL'AND entity_id=(SELECT id FROM public.entities WHERE short_code='IETA'))),'[REG] KL import preview/re-preview/confirm/revert');SELECT extensions.ok(lab_test.merge_ok('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2'),'[REG] KL same-branch merge');SELECT extensions.ok(NOT lab_test.probe($q$SELECT public.merge_students('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa3','cross')$q$),'[REG] KL cross-branch merge denial');RESET ROLE;
SET LOCAL ROLE authenticated;SELECT lab_test.claim('33333333-3333-4333-8333-333333333333','authenticated');SELECT extensions.ok(lab_test.student((SELECT id FROM public.entities WHERE short_code='IETA'),(SELECT id FROM public.branches WHERE branch_code='PG'AND entity_id=(SELECT id FROM public.entities WHERE short_code='IETA'))),'[REG] PG student create/edit, number, masking');SELECT extensions.ok(lab_test.academic((SELECT id FROM public.entities WHERE short_code='IETA'),(SELECT id FROM public.branches WHERE branch_code='PG'AND entity_id=(SELECT id FROM public.entities WHERE short_code='IETA')),'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa3'),'[REG] PG programme/intake/enrolment');SELECT extensions.ok(lab_test.import_flow((SELECT id FROM public.entities WHERE short_code='IETA'),(SELECT id FROM public.branches WHERE branch_code='PG'AND entity_id=(SELECT id FROM public.entities WHERE short_code='IETA'))),'[REG] PG import preview/re-preview/confirm/revert');SELECT extensions.ok(lab_test.merge_ok('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa3','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa4'),'[REG] PG same-branch merge');SELECT extensions.ok(NOT lab_test.probe($q$SELECT public.merge_students('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa3','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','cross')$q$),'[REG] PG cross-branch merge denial');RESET ROLE;
SET LOCAL ROLE authenticated;SELECT lab_test.claim('11111111-1111-4111-8111-111111111111','authenticated');SELECT extensions.ok(NOT lab_test.probe($q$SELECT public.merge_students('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa5','cross entity')$q$),'[REG] Cross-entity merge denial');RESET ROLE;
SET LOCAL ROLE authenticated;SELECT lab_test.claim('55555555-5555-4555-8555-555555555555','authenticated');SELECT extensions.ok(NOT lab_test.student((SELECT id FROM public.entities WHERE short_code='IETA'),(SELECT id FROM public.branches WHERE branch_code='KL'AND entity_id=(SELECT id FROM public.entities WHERE short_code='IETA'))),'[REG] Inactive denial');RESET ROLE;
SET LOCAL ROLE anon;SELECT lab_test.claim(NULL,'anon');SELECT extensions.ok(NOT lab_test.student(lab_test.entity_id('IETA'),lab_test.branch_id('KL')),'[REG] Anonymous denial');RESET ROLE;SELECT*FROM extensions.finish();ROLLBACK;